cypress_script:
describe('Opening links in new windows', () => {
  it('should open a new window when clicking on Click Here', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.contains('Click Here').click();
    cy.url().should('eq', 'http://elementalselenium.com/');
  });

  it('should not navigate away from the original page when Click Here is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/windows');
    cy.contains('Click Here').click();
    cy.url().should('eq', 'http://elementalselenium.com/');
    cy.get('#content').should('be.visible');
    cy.contains('Opening a new window').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Opening links in new windows', () => {
  test('should open a new window when clicking on Click Here', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    await page.click('text=Click Here');
    await page.waitForURL('http://elementalselenium.com/');
  });

  test('should not navigate away from the original page when Click Here is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/windows');
    await page.click('text=Click Here');
    await page.waitForURL('http://elementalselenium.com/');
    await expect(page.locator('#content')).toBeVisible();
    await expect(page.locator('text=Opening a new window')).toBeVisible();
  });
});
